class LaneControlTests(unittest.TestCase):
    def test_bend_slowdown_is_reduced_outside_zone_and_zone_cap_is_unchanged(self):
        self.assertEqual(t.CRUISE, t.SPEED_LIMIT)
        straight = {'center_near': 320., 'center_far': 320.}
        bend = {'center_near': 640., 'center_far': 640.}
        straight_steer, straight_speed = t.lane_control(straight, t.CRUISE)
        bend_steer, bend_speed = t.lane_control(bend, t.CRUISE)
        turn = min(abs(bend_steer) / t._virtual_steering_limit(), 1.0)
        self.assertEqual(straight_steer, 0.0)
        self.assertEqual(straight_speed, t.CRUISE)
        self.assertLessEqual(straight_speed, t.SPEED_LIMIT)
        self.assertGreater(turn, 0.99)
        self.assertAlmostEqual(bend_speed, t.CRUISE * (1.0 - 0.05 * turn))
        self.assertLess(bend_speed, t.CRUISE)
        self.assertLessEqual(bend_speed, t.SPEED_LIMIT)

        _, zone_speed = t.lane_control(bend, t.ZONE_CRUISE)
        self.assertEqual(zone_speed, t.ZONE_CRUISE)




