def recorded_crop(encoded):
    import base64
    return cv2.imdecode(np.frombuffer(base64.b64decode(encoded), np.uint8), cv2.IMREAD_COLOR)


class PerceptionTests(unittest.TestCase):
    def test_recorded_roof_fullframes_cannot_confirm_speed_exit(self):
        import base64
        samples = ['', '']
        for encoded in samples:
            frame = cv2.imdecode(np.frombuffer(base64.b64decode(encoded), np.uint8), cv2.IMREAD_COLOR)
            self.assertEqual(t._oblique_speed40_candidates(frame), [])

    def test_light_edge_observations_confirm_only_as_consistent_pair(self):
        # Original raw pixels with >17px context, including the clipped edge.
        samples = ['', '']
        weak = t.WeakBoardTracker()
        observations = []
        for encoded in samples:
            crop = recorded_crop(encoded)
            frame = np.zeros((480, 640, 3), np.uint8)
            frame[16:114, 565:640] = crop
            raw = t._oblique_speed40_candidates(frame)
            self.assertEqual(len(raw), 1)
            observations.append(raw)
        self.assertEqual(weak.update(observations[0]), [])
        self.assertEqual(weak.update([]), [])
        self.assertEqual(weak.update(observations[1]), [])
        weak.reset()
        self.assertEqual(weak.update(observations[0]), [])
        self.assertEqual(len(weak.update(observations[1])), 1)
        weak.reset()
        weak.update(observations[0])
        shifted = [dict(observations[1][0], bbox=(100, 40, 24, 52))]
        self.assertEqual(weak.update(shifted), [])

    def test_tentative_support_requires_current_strong_consistent_observation(self):
        tentative = dict(sign(size=40), strong=False)
        strong = dict(sign(size=40), strong=True)
        def primed():
            tracker = t.SignTracker(t.ZONE_NEAR_RANGE)
            tracker.update([sign(size=80)], 0.)
            tracker.update([], 5., travel=.1)
            return tracker, t.WeakBoardTracker()
        for sequence in ([tentative, tentative], [strong, tentative],
                         [tentative, None, strong],
                         [tentative, [strong, strong]],
                         [tentative, dict(strong, bbox=(500, 200, 40, 40))]):
            tracker, weak = primed()
            for i, observation in enumerate(sequence):
                raw = [] if observation is None else observation if isinstance(observation, list) else [observation]
                confirmed = weak.update(raw)
                tracker.update(raw if len(raw)==1 else [], 5.1+i*.1,
                               confirmed=bool(confirmed))
            self.assertEqual(tracker.count, 1)
        tracker, weak = primed()
        for i, raw in enumerate(([tentative], [strong])):
            tracker.update(raw, 5.1+i*.1, confirmed=bool(weak.update(raw)))
        self.assertEqual(tracker.count, 2)
        # Spatial evidence still cannot manufacture distinct-encounter rearm.
        tracker, weak = t.SignTracker(t.ZONE_NEAR_RANGE), t.WeakBoardTracker()
        tracker.update([sign(size=80)], 0.)
        for i, raw in enumerate(([tentative], [strong])):
            tracker.update(raw, .1+i*.1, confirmed=bool(weak.update(raw)))
        self.assertEqual(tracker.count, 1)

    def test_parallel_confirmation_needs_two_spatially_consistent_distinct_sights(self):
        tracker = t.SignTracker(t.ZONE_NEAR_RANGE)
        weak = t.WeakBoardTracker()
        tracker.update([sign(size=80)], 0.)
        tracker.update([], 5., travel=.1)
        self.assertTrue(tracker.rearmed)
        candidate = sign(size=40)
        self.assertFalse(tracker.update([candidate], 5.1,
                         confirmed=bool(weak.update([candidate]))))
        self.assertEqual(tracker.count, 1)
        self.assertTrue(tracker.update([candidate], 5.2,
                        confirmed=bool(weak.update([candidate]))))
        self.assertEqual(tracker.count, 2)

    def test_unconfirmed_observations_cannot_release_distinct_tracker(self):
        tracker = t.SignTracker(t.ZONE_NEAR_RANGE)
        tracker.update([sign(size=80)], 0.)
        tracker.update([], 5., travel=.1)
        for now in (5.1, 5.2, 5.3):
            self.assertFalse(tracker.update([sign(size=40)], now, confirmed=False))
        self.assertEqual(tracker.count, 1)

