    def test_fitted_ellipse_axis_pairing_recovers_known_geometry(self):
        for angle in (0, 35, 90):
            points = cv2.ellipse2Poly((100, 100), (40, 15), angle, 0, 358, 2)
            (cx, cy), (d1, d2), theta = cv2.fitEllipse(points.reshape(-1, 1, 2).astype(np.float32))
            a, b = d1 / 2., d2 / 2.
            x, y = points[:, 0] - cx, points[:, 1] - cy
            rad = np.deg2rad(theta)
            u, v = x*np.cos(rad)+y*np.sin(rad), -x*np.sin(rad)+y*np.cos(rad)
            radius = np.sqrt((u/a)**2 + (v/b)**2)
            self.assertAlmostEqual(float(np.median(radius)), 1., delta=.03)
            self.assertLess(float(np.median(np.abs(radius-1))), .03)

    def test_real_blue_crops_with_and_without_reference_images(self):
        import base64
        modules = []
        original_imread = cv2.imread
        for absent in (False, True):
            module_spec = importlib.util.spec_from_file_location('task3_no_refs' if absent else 'task3_refs', SOURCE)
            module = importlib.util.module_from_spec(module_spec)
            def reference_read(path, *args):
                return None if absent else original_imread(str(ROOT / 'task3/reference_images' / Path(path).name), *args)
            with patch.object(cv2, 'imread', side_effect=reference_read):
                module_spec.loader.exec_module(module)
            modules.append(module)
        for module in modules:
            for name, expected, encoded in BLUE_CROPS:
                with self.subTest(mode=module.__name__, crop=name):
                    crop = cv2.imdecode(np.frombuffer(base64.b64decode(encoded), np.uint8), cv2.IMREAD_COLOR)
                    frame = FRAME.copy()
                    h, w = crop.shape[:2]
                    frame[100:100+h, 100:100+w] = crop
                    hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
                    signs = module.detect_signs(frame, hsv,
                        module._components(module._colour_mask(hsv, 'red'), 120),
                        module._components(module._colour_mask(hsv, 'blue'), 120))
                    labels = {s['label'] for s in signs if s['label'] in ('Parking', 'Hospital')}
                    self.assertEqual(labels, {expected} if expected else set())

