            crop = recorded_crop(encoded)
            variants = (crop, cv2.flip(crop, 1),
                        cv2.resize(crop, None, fx=.5, fy=.5), crop[:, :crop.shape[1] // 2])
            for index, variant in enumerate(variants):
                with self.subTest(board=label, variant=index):
                    frame = FRAME.copy()
                    h, w = variant.shape[:2]
                    frame[40:40+h, 400:400+w] = variant
