                    self.assertEqual(t._whiteboard_speed_candidates(hsv), [])
                    signs = t.detect_signs(frame, hsv,
                        t._components(t._colour_mask(hsv, 'red'), 120),
                        t._components(t._colour_mask(hsv, 'blue'), 120))
                    self.assertNotIn('Speed40', {s['label'] for s in signs})

