    def test_weak_exit_tracker_rejects_alternating_boards(self):
        tracker = t.WeakBoardTracker()
        boards = [
            {"label": "Speed40", "area": 400, "bbox": (80, 40, 20, 40)},
            {"label": "Speed40", "area": 400, "bbox": (500, 40, 20, 40)},
            {"label": "Speed40", "area": 400, "bbox": (85, 42, 21, 40)},
        ]
        for board in boards:
            self.assertEqual(tracker.update([board]), [])
        self.assertEqual(tracker.streak, 1)
        self.assertEqual(tracker.update([]), [])
        self.assertEqual(tracker.streak, 0)

    def test_late_hospital_detection_arms_after_confirmation(self):
        m = mission()
        with patch.object(t, 'estimate_sign_range', return_value=(.70, .15)):
            m._hospital(FRAME, [sign('Hospital')], 0)
