class MissionTests(unittest.TestCase):
    def setUp(self):
        self.m = mission()
        self.signs = patch.object(t, 'detect_signs', return_value=[]).start()
        self.obstacles = patch.object(t, 'detect_obstacles', return_value=[]).start()
        self.addCleanup(patch.stopall)
        self.lane = dict(valid=True, side='right', center_near=320., center_far=320.,
                         divider=None, edge=None)
        patch.object(t, 'detect_lane', return_value=self.lane).start()
        self.m._marker = Mock(return_value=None)

    def test_first_sight_caps_even_distant_sign(self):
        self.signs.return_value = [sign(size=16)]
        self.assertLessEqual(self.m.step(FRAME, 0)[1], t.ZONE_LIMIT)
        self.assertTrue(self.m.zone)

    def test_cap_retained_without_exit_confirmation(self):
        self.signs.return_value = [sign(size=80)]
        self.m.step(FRAME, 0)
        self.m.step(FRAME, .1)
        self.signs.return_value = []
        for now in (1, 5, 15):
            self.assertLessEqual(self.m.step(FRAME, now)[1], t.ZONE_LIMIT)
        self.assertTrue(self.m.zone)

    def test_distinct_second_sign_releases_zone(self):
        self.signs.return_value = [sign(size=80)]
        self.m.step(FRAME, 0)
        self.m.step(FRAME, .1)
        self.signs.return_value = []
        for now in np.arange(.2, 6, .1):
            self.m.step(FRAME, float(now))
        self.signs.return_value = [sign(size=20)]
        self.m.step(FRAME, 6)
        _, speed = self.m.step(FRAME, 6.1)
        self.assertTrue(self.m.zone_done)
        self.assertFalse(self.m.zone)
        self.assertGreater(speed, t.ZONE_LIMIT)

    def test_same_sign_after_long_flicker_does_not_release(self):
        self.signs.return_value = [sign(size=80)]
        self.m.step(FRAME, 0)
        self.m.step(FRAME, .1)
        self.signs.return_value = []
        for now in np.arange(.2, 6, .1):
            self.m.step(FRAME, float(now))
        self.signs.return_value = [sign(size=80)]
        for now in (6, 6.1, 6.2):
            self.assertLessEqual(self.m.step(FRAME, now)[1], t.ZONE_LIMIT)
        self.assertFalse(self.m.zone_done)

    def test_recorded_parking_board_does_not_release_rearmed_zone(self):
        self.signs.return_value = [sign('Speed40', size=80)]
        self.m.step(FRAME, 0.)
        self.signs.return_value = []
        for now in np.arange(.1, 5., .1):
            self.m.step(FRAME, float(now))
        self.assertTrue(self.m.speed40.rearmed)
        crop = recorded_crop(OBLIQUE_PARKING_CROPS[1][1])
        frame = FRAME.copy()
        h, w = crop.shape[:2]
        frame[40:40+h, 400:400+w] = crop
        for now in (5., 5.2, 5.4, 5.6, 5.8):
            _, speed = self.m.step(frame, now)
            self.assertTrue(self.m.zone)
            self.assertFalse(self.m.zone_done)
            self.assertEqual(self.m.speed40.count, 1)
            self.assertLessEqual(speed, t.ZONE_CRUISE)
        self.assertEqual(self.m.step(None, 6.), (0., 0.))
        self.m.step(FRAME, 6.5)
        self.assertTrue(self.m.zone)
        self.assertFalse(self.m.zone_done)

    def test_weak_board_range_still_requires_rearm_and_two_confirmations(self):
        tracker = t.SignTracker(t.ZONE_NEAR_RANGE)
        with patch.object(t, 'estimate_sign_range', side_effect=[(.60, .1), (.29, .1)] +
                          [(.60, .1)] * 8):
            tracker.update([sign(size=80)], 0.)
            tracker.update([sign(size=80)], .1)
            for now in np.arange(.2, 4.6, .1):
                tracker.update([], float(now), travel=.02)
            self.assertTrue(tracker.rearmed)
            self.assertFalse(tracker.update([sign(size=20)], 4.6))
            self.assertTrue(tracker.update([sign(size=20)], 4.7))
            self.assertEqual(tracker.count, 2)

        tracker = t.SignTracker(t.ZONE_NEAR_RANGE)
        with patch.object(t, 'estimate_sign_range', return_value=(.60, .1)):
            tracker.update([sign(size=80)], 0.)
            self.assertFalse(tracker.update([sign(size=20)], .1))
            self.assertEqual(tracker.count, 1)

    def test_hospital_never_counts_continuing_movement(self):
        self.m.halt_started = 0
        for now in range(12):
            frame = np.full_like(FRAME, (now % 2) * 255)
            self.m._hospital(frame, [], now)
        self.assertIsNone(self.m.rest_time)
        self.assertFalse(self.m.hospital_done)

    def test_hospital_movement_resets_hold(self):
        self.m.halt_started = 0
        for now in (0, .1, .2, 1, 2, 3):
            self.m._hospital(FRAME, [], now)
        self.assertIsNotNone(self.m.rest_time)
        self.m._hospital(np.full_like(FRAME, 255), [], 4)
        self.assertIsNone(self.m.rest_time)
        self.m._hospital(FRAME, [], 5)
        for now in (5.1, 5.2, 6, 7, 8, 9, 10):
            self.m._hospital(FRAME, [], now)
        self.assertFalse(self.m.hospital_done)
        self.m._hospital(FRAME, [], 11.1)
        self.assertTrue(self.m.hospital_done)

    def test_hospital_completes_once_and_school_is_ignored(self):
        self.assertIsNone(self.m._hospital(FRAME, [sign('School')], 0))
        self.m.halt_started = 0
        for now in (0, .1, .2, 6.1):
            self.m._hospital(FRAME, [], now)
        self.assertTrue(self.m.hospital_done)
        self.m._hospital = Mock(side_effect=AssertionError('second halt'))
        self.m.step(FRAME, 6.2)

